function groupBy<T, K extends keyof T>(arr: T[], key: K): {[key in K]: T[]} {
  return arr.reduce((acc, item) => {
    const keyValue = item[key];
    if (!acc[keyValue]) {
      acc[keyValue] = [];
    }
    acc[keyValue].push(item);
    return acc;
  }, {} as {[key in K]: T[]});
}

const groupedPeople = groupBy(people, 'age');
